<?php
session_start();require_once '../includes/auth.php';require_once '../includes/messages.php';require_role('coach');require '../config/database.php';$result_id=filter_input(INPUT_GET,'result_id',FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT r.id,r.session_id,f.feedback_text,s.title,CONCAT(u.first_name,' ',u.last_name) rower_name FROM results r JOIN sessions s ON s.id=r.session_id JOIN users u ON u.id=r.rower_id LEFT JOIN feedback f ON f.result_id=r.id WHERE r.id=? AND s.coach_id=?");$q->execute([$result_id,(int)$_SESSION['user_id']]);$data=$q->fetch();if(!$data){http_response_code(404);exit('Submission not found.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null))$error='Your form expired. Please try again.';elseif(strlen(trim($_POST['feedback']??''))>5000)$error='Feedback must be 5,000 characters or fewer.';else{$text=trim($_POST['feedback']??'');$pdo->prepare('INSERT INTO feedback (result_id,coach_id,feedback_text) VALUES (?,?,?) ON DUPLICATE KEY UPDATE coach_id=VALUES(coach_id),feedback_text=VALUES(feedback_text),updated_at=CURRENT_TIMESTAMP')->execute([$result_id,(int)$_SESSION['user_id'],$text]);set_session_message('success','Coach feedback saved.');header('Location: /pages/session-view.php?id='.$data['session_id']);exit;}}$page_title='Coach feedback - OarNote';require '../includes/header.php';?>
<header class="page-header"><div><p class="eyebrow">Coach feedback</p><h1><?= htmlspecialchars($data['rower_name']) ?></h1><p><?= htmlspecialchars($data['title']) ?></p></div></header><div class="form-shell card"><?php if($error): ?><div class="alert alert-error"><?= htmlspecialchars($error) ?></div><?php endif ?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token()) ?>"><div class="form-group"><label class="form-label">Overall feedback</label><textarea name="feedback" maxlength="5000" placeholder="Good session. Keep working on controlling the recovery."><?= htmlspecialchars($data['feedback_text']??'') ?></textarea><small class="form-help">One comment for the rower's entire session.</small></div><div class="form-actions"><a class="btn btn-secondary" href="/pages/session-view.php?id=<?= (int)$data['session_id'] ?>">Cancel</a><button class="btn btn-primary" type="submit">Save feedback</button></div></form></div><?php require '../includes/footer.php';?>
